function smart_sort_array($set, $order) {
    // Check if order is valid (ascending or descending)
    if ($order !== 'asc' && $order !== 'desc') {
        throw new InvalidArgumentException("Order must be either 'asc' or 'desc'");
    }

    usort($set, function($a, $b) use ($order) {
        if ($a['age'] < $b['age']) return ($order === 'asc') ? -1 : 1;
        elseif ($a['age'] > $b['age']) return ($order === 'asc') ? 1 : -1;
        else return 0; // If ages are equal, keep the original order
    });

    return $set;
}

// Example usage:
$example_set = [
    ['name' => 'Alice', 'address' => '123 Main St', 'age' => 25],
    ['name' => 'Bob', 'address' => '456 Oak Ave', 'age' => 30],
    ['name' => 'Charlie', 'address' => '789 Pine Ln', 'age' => 22]
];

try {
    print_r(smart_sort_array($example_set, 'asc'));  // Should output the sorted array by age
} catch (InvalidArgumentException $e) {
    echo $e->getMessage();
}
